import requests
import json

url = "https://partner.shopeemobile.com/api/v2/business_insights/get_marketing_hot_listing?access_token=[REDACTED_SECRET]&partner_id=partner_id&shop_id=shop_id&sign=[REDACTED_SECRET]&timestamp=timestamp"

payload=json.dumps({
  "end_time": 0,
  "period": "real_time/yesterday/past7days/past30days/monthday/week/",
